class Solution:
    def maximumTop(self, nums: List[int], k: int) -> int:
        if len(nums) == 1:
            if k%2 != 0:
                return -1
            return nums[0]

        if k == 0:
            return nums[0]
        if k == len(nums):
            return max(nums[:-1])
        if k > len(nums):
            return max(nums)
        if k == 1:
            return nums[1]
        m = max(nums[:k-1])
        m = max(m, nums[k])
        return m

class Solution:
    def maximumSubsequenceCount(self, text: str, pattern: str) -> int:
        total = count_a = count_b = 0
        for c in text:
            if c == pattern[1]:
                total += count_a
                count_b += 1
            if c == pattern[0]:
                count_a += 1

        return total + max(count_a, count_b)

